  FT["PH-H8932"] = {"id":"PH-H8932","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10480_2013.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Quezon市","en":"An Act Creating Twenty-Two (22) Additional Branches of the Metropolitan Trial Court in the National Capital Judicial Region to be Stationed at the City of Quezon, Further Amending for the Purpose Batas Pambansa Blg. 129, Otherwise Known as \"The Judiciary Reorganization Act of 1980ö, as Amended, and Appropriating Funds Therefor","orig":"An Act Creating Twenty-Two (22) Additional Branches of the Metropolitan Trial Court in the National Capital Judicial Region to be Stationed at the City of Quezon, Further Amending for the Purpose Batas Pambansa Blg. 129, Otherwise Known as \"The Judiciary Reorganization Act of 1980ö, as Amended, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 10480","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-04-16","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10480_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8932-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Twenty-two (22) additional Metropolitan Trial Court branches for Quezon City, with seats thereat, are hereby created in the National Capital Judicial Region."}},{"id":"PH-H8932-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Supreme Court shall assign the respective branch numbers for the newly created branches."}},{"id":"PH-H8932-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Chief Justice of the Supreme Court, in coordination with the Secretary of the Department of Justice, shall immediately include in the Court’s program the implementation of this Act. The funding therefor shall likewise be included in the annual General Appropriations Act. The funds necessary for the operation of the Courts herein created shall be appropriated and released only upon the actual organization of the Courts and the appointment of its personnel."}},{"id":"PH-H8932-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 27 of Batas Pambansa Blg. 129, otherwise known as \"The Judiciary Reorganization Act of 1980″, as amended, as well as other provisions that may be inconsistent herewith, are hereby deemed repealed, modified and/or further amended."}},{"id":"PH-H8932-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after completion of its publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p127"};
